/**
 * Files the pipeline derives from a grant's document (raw-text.txt, summary.json, questions.json),
 * stored under `<grant>/` in ARTIFACTS_BUCKET. They live outside the grant bucket because the
 * Knowledge Base indexes that whole bucket. Reads fall back to the grant bucket for files written
 * before the move.
 */

import {
  GetObjectCommand,
  PutObjectCommand,
  ListObjectsV2Command,
  CopyObjectCommand,
  DeleteObjectsCommand,
} from "@aws-sdk/client-s3";

export function artifactsBucket() {
  const bucket = process.env.ARTIFACTS_BUCKET;
  if (!bucket) throw new Error("ARTIFACTS_BUCKET is not set");
  return bucket;
}

export function isMissingObject(error) {
  return error?.name === "NoSuchKey" || error?.$metadata?.httpStatusCode === 404;
}

export async function getArtifact(s3, key, legacyBucket = process.env.BUCKET) {
  try {
    return await s3.send(new GetObjectCommand({ Bucket: artifactsBucket(), Key: key }));
  } catch (error) {
    if (!legacyBucket || !isMissingObject(error)) throw error;
    return s3.send(new GetObjectCommand({ Bucket: legacyBucket, Key: key }));
  }
}

export async function readArtifactText(s3, key, legacyBucket = process.env.BUCKET) {
  const response = await getArtifact(s3, key, legacyBucket);
  const chunks = [];
  for await (const chunk of response.Body) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

export function putArtifact(s3, key, body, contentType, metadata) {
  return s3.send(
    new PutObjectCommand({ Bucket: artifactsBucket(), Key: key, Body: body, ContentType: contentType, ...(metadata && { Metadata: metadata }) })
  );
}

export async function listKeys(s3, bucket, prefix) {
  const keys = [];
  let continuationToken;
  do {
    const listed = await s3.send(new ListObjectsV2Command({ Bucket: bucket, Prefix: prefix, ContinuationToken: continuationToken }));
    for (const object of listed.Contents || []) keys.push(object.Key);
    continuationToken = listed.IsTruncated ? listed.NextContinuationToken : undefined;
  } while (continuationToken);
  return keys;
}

const listArtifactKeys = (s3, grantName) => listKeys(s3, artifactsBucket(), `${grantName}/`);

async function deleteKeys(s3, bucket, keys) {
  for (let i = 0; i < keys.length; i += 1000) {
    await s3.send(
      new DeleteObjectsCommand({
        Bucket: bucket,
        Delete: { Objects: keys.slice(i, i + 1000).map((Key) => ({ Key })), Quiet: true },
      })
    );
  }
  return keys.length;
}

export function copySource(bucket, key) {
  return [bucket, ...key.split("/")].map(encodeURIComponent).join("/");
}

export async function copyArtifacts(s3, fromName, toName) {
  const bucket = artifactsBucket();
  const keys = await listArtifactKeys(s3, fromName);
  for (const key of keys) {
    await s3.send(
      new CopyObjectCommand({
        Bucket: bucket,
        CopySource: copySource(bucket, key),
        Key: `${toName}/${key.slice(fromName.length + 1)}`,
      })
    );
  }
  return keys.length;
}

export async function deleteArtifacts(s3, grantName) {
  return deleteKeys(s3, artifactsBucket(), await listArtifactKeys(s3, grantName));
}

/**
 * A live grant's new version (its document and the files derived from it) waits under
 * `_pending/<grant>/` in ARTIFACTS_BUCKET until it publishes, so the published files stay as they
 * are. The Knowledge Base indexes only the grant bucket, and per-grant listings (`<grant>/`) skip it.
 */
export const PENDING_PREFIX = "_pending/";
export const DOCUMENT_FILES = ["NOFO-File-PDF", "NOFO-File-TXT"];

export const pendingDir = (grantName) => `${PENDING_PREFIX}${grantName}/`;

/**
 * S3 metadata on a staged derived file: the version of the staged document it came from, so a
 * stopped older run that still writes one can't have it published with a newer document.
 */
export const SOURCE_VERSION_METADATA = "source-version";
export const sourceVersionMetadata = (documentVersionId) =>
  documentVersionId ? { [SOURCE_VERSION_METADATA]: documentVersionId } : undefined;
export const isPendingKey = (key) => typeof key === "string" && key.startsWith(PENDING_PREFIX);

/** The grant a published (`<grant>/<file>`) or staged document key belongs to. */
export function grantOfKey(key) {
  const path = isPendingKey(key) ? key.slice(PENDING_PREFIX.length) : key;
  return path.slice(0, path.lastIndexOf("/"));
}

/** Where a pipeline run writes the files it derives: beside a staged document, else the grant's own folder. */
export const artifactDirOf = (grantName, documentKey) => (isPendingKey(documentKey) ? pendingDir(grantName) : `${grantName}/`);

/** A grant with this metadata status may have a published version, so a new document for it is staged. */
export const stagesNewVersion = (status) => status === "active" || status === "archived";

export const listPending = (s3, grantName) => listKeys(s3, artifactsBucket(), pendingDir(grantName));

export async function deletePending(s3, grantName, { keep = [] } = {}) {
  const keys = (await listPending(s3, grantName)).filter((key) => !keep.includes(key));
  return deleteKeys(s3, artifactsBucket(), keys);
}
